/// `ResponseCookie`, `SameSite` and the `cookie` header reader.
pub mod cookie;

pub use cookie::{cookie_value, ResponseCookie, SameSite};

/// The browser-enforced host-only cookie name prefix (RFC 6265bis §4.1.3.2).
pub const HOST_PREFIX: &str = "__Host-";

/// A host-only `__Host-` browser session cookie. The prefix, root path,
/// `Secure` flag and absence of `Domain` are enforced together.
///
/// The suffix is the part of the name AFTER the prefix: pass
/// `"session"` to get `__Host-session`. An empty suffix, or one starting with
/// `-`, is an error rather than a cookie a browser will drop.
///
/// ```ignore
/// let cookie = http_cookies::host_session("session", token)?;
/// let header = http_cookies::render(&cookie)?;
/// ```
pub fn host_session(
    name_suffix: impl Into<String>,
    value: impl Into<String>,
) -> Result<ResponseCookie, String> {
    ResponseCookie::session(host_name(name_suffix)?, value)?.path("/")
}

/// The full prefixed cookie name for a suffix, so a reader and a writer
/// cannot disagree about the spelling.
///
/// Refuses an empty suffix and a suffix starting with `-`, which are the two
/// shapes that produce a name a browser drops without saying so. Every other
/// name rule belongs to `ResponseCookie`, which refuses a name that is not an
/// HTTP token.
pub fn host_name(name_suffix: impl Into<String>) -> Result<String, String> {
    let suffix = name_suffix.into();
    if suffix.is_empty() || suffix.starts_with('-') {
        return Err("host cookie suffix is invalid".into());
    }
    Ok(format!("{HOST_PREFIX}{suffix}"))
}

/// Render a `Set-Cookie` value, re-checking the browser's `__Host-` rules on
/// the wire form when the name carries the prefix.
///
/// A cookie whose name does NOT carry the prefix renders exactly as
/// `ResponseCookie::render` renders it. This function adds a check; it never
/// refuses something the platform accepts for a name the rule does not cover.
pub fn render(cookie: &ResponseCookie) -> Result<String, String> {
    let rendered = cookie.render()?;
    check_host_rules(&rendered)?;
    Ok(rendered)
}

/// Expire a `__Host-` cookie immediately, with the attributes the browser
/// requires in order to match the cookie it is being asked to drop.
pub fn clear_host_session(name_suffix: impl Into<String>) -> Result<String, String> {
    render(&host_session(name_suffix, "")?.max_age_secs(0))
}

/// Read a `__Host-` cookie from forwarded `cookie` headers by SUFFIX, so a
/// reader that forgets the prefix cannot silently see no session.
///
/// The lookup is [`cookie_value`] over the prefixed name, so it inherits the
/// first-match-wins rule exactly.
pub fn host_cookie_value<'a>(
    headers: &'a [(String, String)],
    name_suffix: &str,
) -> Option<&'a str> {
    let name = host_name(name_suffix).ok()?;
    cookie_value(headers, &name)
}

/// Verify a rendered `Set-Cookie` value against the three conditions a
/// browser applies to a `__Host-` name. A name without the prefix passes
/// unexamined.
fn check_host_rules(rendered: &str) -> Result<(), String> {
    let Some((name, rest)) = rendered.split_once('=') else {
        return Err("rendered cookie has no name".into());
    };
    if !name.starts_with(HOST_PREFIX) {
        return Ok(());
    }
    if name.len() == HOST_PREFIX.len() {
        return Err("__Host- cookies require a non-empty name suffix".into());
    }
    // `rest` is `value; Attr; Attr=…`; the value cannot contain `;`, because
    // `ResponseCookie` refuses that byte, so skipping the first segment
    // yields exactly the attributes.
    let attributes: Vec<&str> = rest.split(';').skip(1).map(str::trim).collect();
    let has_flag = |flag: &str| {
        attributes
            .iter()
            .any(|attribute| attribute.eq_ignore_ascii_case(flag))
    };
    let attribute_value = |key: &str| {
        attributes.iter().find_map(|attribute| {
            let (name, value) = attribute.split_once('=')?;
            name.trim().eq_ignore_ascii_case(key).then(|| value.trim())
        })
    };
    if attribute_value("Path") != Some("/") {
        return Err("__Host- cookies require Path=/".into());
    }
    if !has_flag("Secure") {
        return Err("__Host- cookies require Secure".into());
    }
    if attribute_value("Domain").is_some() {
        return Err("__Host- cookies must not carry Domain".into());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn host_session_renders_the_prefixed_secure_root_path_cookie() {
        let rendered = render(&host_session("ferrite-session", "opaque").unwrap()).unwrap();
        assert_eq!(
            rendered,
            "__Host-ferrite-session=opaque; Path=/; HttpOnly; Secure; SameSite=Strict"
        );
    }

    #[test]
    fn an_unusable_suffix_is_refused_at_construction() {
        assert!(host_session("", "opaque").is_err());
        assert!(host_session("-leading", "opaque").is_err());
        assert!(host_name("").is_err());
        assert_eq!(host_name("session").unwrap(), "__Host-session");
        // Name rules beyond the prefix stay with ResponseCookie.
        assert!(host_session("bad name", "opaque").is_err());
        assert!(host_session("session", "has;semicolon").is_err());
    }

    #[test]
    fn render_catches_a_prefix_invariant_broken_after_construction() {
        // The platform crate's own validation carries no `__Host-` rule, so
        // this cookie builds and renders through `ResponseCookie::render`.
        let widened = host_session("session", "opaque")
            .unwrap()
            .path("/admin")
            .unwrap();
        assert!(widened.render().is_ok());
        let refusal = render(&widened).unwrap_err();
        assert!(refusal.contains("Path=/"), "{refusal}");

        let readable = host_session("session", "opaque").unwrap().script_readable();
        // Dropping HttpOnly is legal for a `__Host-` cookie: the browser rule
        // is Secure + Path=/ + no Domain, and nothing else.
        assert!(render(&readable).is_ok());
    }

    #[test]
    fn a_cookie_without_the_prefix_renders_exactly_as_the_platform_renders_it() {
        let plain = ResponseCookie::session("ferrite_session", "abc_123")
            .unwrap()
            .max_age_secs(3600)
            .path("/admin")
            .unwrap();
        assert_eq!(render(&plain).unwrap(), plain.render().unwrap());
        assert_eq!(
            render(&plain).unwrap(),
            "ferrite_session=abc_123; Path=/admin; Max-Age=3600; HttpOnly; Secure; SameSite=Strict"
        );
    }

    #[test]
    fn same_site_none_still_renders_secure_and_passes() {
        let cross_site = host_session("session", "opaque")
            .unwrap()
            .same_site(SameSite::None);
        let rendered = render(&cross_site).unwrap();
        assert!(rendered.contains("; Secure"), "{rendered}");
        assert!(rendered.ends_with("SameSite=None"), "{rendered}");
    }

    #[test]
    fn clearing_expires_the_same_name_the_setter_wrote() {
        let cleared = clear_host_session("session").unwrap();
        assert_eq!(
            cleared,
            "__Host-session=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict"
        );
        assert!(clear_host_session("").is_err());
    }

    #[test]
    fn a_reader_addresses_the_prefixed_name() {
        let headers = vec![(
            "cookie".into(),
            "other=1; __Host-session=abc; session=decoy".into(),
        )];
        assert_eq!(host_cookie_value(&headers, "session"), Some("abc"));
        assert_eq!(host_cookie_value(&headers, "absent"), None);
        assert_eq!(host_cookie_value(&headers, ""), None);
        // The unprefixed name is a DIFFERENT cookie, and a browser gives it
        // none of the guarantees. Reading by suffix is what keeps a setter
        // and a reader on the same one.
        assert_eq!(cookie_value(&headers, "session"), Some("decoy"));
    }
}
